tool_audit.command:
/bin/zsh -lc "./run_python -c 'import tempfile, app; from pathlib import Path
with tempfile.TemporaryDirectory() as d:
 q=app.Queue(Path(d)/\"q.db\"); src={\"items\":[1,{\"ok\":True}]}; q.put(\"a\",src); src[\"items\"].append(2); claim=q.claim(\"w\",0,1); assert claim[\"payload\"] == {\"items\":[1,{\"ok\":True}]}; claim[\"payload\"][\"items\"].clear(); assert q.claim(\"w2\",0,1) is None; assert q.claim(\"w2\",1,1)[\"payload\"] == {\"items\":[1,{\"ok\":True}]}
 try: q.put(\"bad\", float(\"nan\"))
 except ValueError: pass
 else: raise AssertionError(\"NaN accepted\")
 try: q.put(\"bad\", object())
 except TypeError: pass
 else: raise AssertionError(\"unsupported value accepted\")
 assert q.claim(\"w\",2,1) is None
 assert q.ack(claim[\"receipt\"],2) is False
 print(\"payload snapshot/isolation, invalid payload rejection, and unsuccessful ack checks passed\")' && git diff -- app.py"

